#!/usr/bin/env python3
"""Собирает nouns-rule.js из content/theory/09-nouns-rule.html (как reported-speech.js)."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
html = (ROOT / 'content/theory/09-nouns-rule.html').read_text(encoding='utf-8').strip()
js = '''"use strict";
// Published theory only; no exercise answers or grading data. Generated by scripts/build_nouns_rule.py.
const NOUNS_RULE_CONTENT = %s;
function nounsRuleHtml(prefix='') {
  const safePrefix=String(prefix).replace(/[^a-zA-Z0-9_-]/g,'');
  return NOUNS_RULE_CONTENT
    .replace(/id="([^"]+)"/g,(_,id)=>'id="'+safePrefix+id+'" data-nouns-id="'+id+'"')
    .replace(/href="#(nr-[^"]+)"/g,(_,id)=>'href="#theory/nouns/'+id+'" data-nouns-anchor="'+id+'"');
}
function revealNounsAnchor(container,anchor) {
  const root=container?.matches?.('.nr')?container:container?.querySelector?.('.nr');
  if(!root)return;
  const id=String(anchor||'').replace(/^#?(?:theory\\/nouns\\/)?/,'');
  if(!id)return;
  const target=[root,...root.querySelectorAll('[data-nouns-id]')].find(node=>node.dataset.nounsId===id||node.id===id);
  if(!target)return;
  for(let node=target.closest('details');node;node=node.parentElement?.closest('details'))node.open=true;
  const spot=target.closest('details')||target.closest('h3')||target.closest('.mv-sec')||target;
  const scrollArea=root.closest('.reference-reader,.rule-dialog-content');
  if(scrollArea){
    const nav=root.querySelector('.mv-nav');
    scrollArea.scrollTop+=spot.getBoundingClientRect().top-scrollArea.getBoundingClientRect().top-(nav?.getBoundingClientRect().height||0)-16;
  }else spot.scrollIntoView({block:'start',behavior:'instant'});
}
function initialiseNounsRule(container) {
  const root=container?.matches?.('.nr')?container:container?.querySelector?.('.nr');
  if(!root||root.dataset.initialised)return;
  root.dataset.initialised='true';
  root.querySelectorAll('.mv-scroll').forEach((table,index)=>{
    table.tabIndex=0;table.setAttribute('role','region');
    table.setAttribute('aria-label',(table.closest('.mv-sec')?.querySelector('h2')?.textContent||'Таблица правила').trim()+' · таблица '+(index+1));
  });
  root.querySelectorAll('.mv-table').forEach(table=>{
    const heads=[...table.querySelectorAll('thead th')].map(th=>th.textContent.trim());
    table.querySelectorAll('tbody tr').forEach(row=>[...row.children].forEach((cell,i)=>cell.setAttribute('data-label',heads[i]||'')));
  });
  root.addEventListener('click',event=>{
    const link=event.target.closest?.('[data-nouns-anchor]');
    if(link&&root.contains(link)&&event.button===0&&!event.metaKey&&!event.ctrlKey&&!event.altKey&&!event.shiftKey){
      event.preventDefault();event.stopPropagation();
      revealNounsAnchor(root,link.dataset.nounsAnchor);return;
    }
    const word=event.target.closest?.('.nr-words button');
    if(word&&root.contains(word)){
      const box=word.closest('.mv-sec').querySelector('.nr-verdict');
      word.parentElement.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b===word)));
      const countable=word.dataset.k==='c';
      box.hidden=false;box.className='nr-verdict '+(countable?'nr-v-c':'nr-v-u');
      box.replaceChildren();
      const title=document.createElement('b');title.textContent=word.textContent+' — '+(countable?'исчисляемое':'неисчисляемое');
      const good=document.createElement('span');good.className='mv-ok';good.textContent=word.dataset.ok;
      const bad=document.createElement('span');bad.className='mv-x';bad.textContent=word.dataset.bad;
      box.append(title,good,bad);return;
    }
    const option=event.target.closest?.('.nr-opts button');
    if(option&&root.contains(option)){
      const question=option.closest('.nr-q');
      if(question.dataset.done)return;
      question.dataset.done='1';
      const right=option.hasAttribute('data-ok');
      question.querySelectorAll('.nr-opts button').forEach(b=>{b.disabled=true;if(b.hasAttribute('data-ok'))b.classList.add('nr-right');});
      if(!right)option.classList.add('nr-wrong');
      question.classList.add(right?'nr-q-ok':'nr-q-bad');
      const quiz=question.closest('.nr-quiz');
      const all=quiz.querySelectorAll('.nr-q'),done=quiz.querySelectorAll('.nr-q[data-done]');
      if(all.length===done.length){
        const score=quiz.querySelectorAll('.nr-q-ok').length;
        let foot=quiz.querySelector('.nr-score');
        if(!foot){foot=document.createElement('div');foot.className='nr-score';quiz.append(foot);}
        foot.replaceChildren();
        const text=document.createElement('span');text.textContent='Результат: '+score+' из '+all.length;
        const again=document.createElement('button');again.type='button';again.className='nr-again';again.textContent='Ещё раз';
        foot.append(text,again);
      }
      return;
    }
    const again=event.target.closest?.('.nr-again');
    if(again&&root.contains(again)){
      const quiz=again.closest('.nr-quiz');
      quiz.querySelectorAll('.nr-q').forEach(q=>{delete q.dataset.done;q.classList.remove('nr-q-ok','nr-q-bad');q.querySelectorAll('button').forEach(b=>{b.disabled=false;b.classList.remove('nr-right','nr-wrong');});});
      quiz.querySelector('.nr-score')?.remove();
    }
  });
}
''' % json.dumps(html, ensure_ascii=False)
(ROOT / 'nouns-rule.js').write_text(js, encoding='utf-8')
print('nouns-rule.js', len(js))
